INSERT IGNORE INTO authors (id, name, bio, created_at) VALUES
  (1, 'Jane Austen', 'English novelist whose sharp, witty studies of courtship and class in Regency England remain widely read.', UTC_TIMESTAMP(6)),
  (2, 'Mary Shelley', 'English writer who, at nineteen, began the novel widely regarded as the first work of science fiction.', UTC_TIMESTAMP(6)),
  (3, 'Bram Stoker', 'Irish author and theatre manager best known for defining the modern vampire story.', UTC_TIMESTAMP(6)),
  (4, 'H. G. Wells', 'English writer whose scientific romances imagined time travel, alien invasion and invisible men.', UTC_TIMESTAMP(6)),
  (5, 'Jules Verne', 'French novelist of extraordinary voyages who blended adventure with the science of his day.', UTC_TIMESTAMP(6)),
  (6, 'Arthur Conan Doyle', 'Scottish physician and writer, creator of the consulting detective Sherlock Holmes.', UTC_TIMESTAMP(6)),
  (7, 'Charles Dickens', 'Victorian novelist celebrated for vivid characters and his portraits of poverty and social injustice.', UTC_TIMESTAMP(6)),
  (8, 'Herman Melville', 'American novelist and poet who drew on his years at sea for his fiction.', UTC_TIMESTAMP(6)),
  (9, 'Mark Twain', 'American humorist and novelist whose vernacular voice captured life along the Mississippi.', UTC_TIMESTAMP(6)),
  (10, 'Lewis Carroll', 'English mathematician and writer of playful, logic-twisting nonsense literature.', UTC_TIMESTAMP(6)),
  (11, 'L. Frank Baum', 'American author who created the land of Oz and its many sequels.', UTC_TIMESTAMP(6)),
  (12, 'J. M. Barrie', 'Scottish novelist and playwright, creator of the boy who would not grow up.', UTC_TIMESTAMP(6)),
  (13, 'Robert Louis Stevenson', 'Scottish novelist and travel writer known for adventure and tales of the uncanny.', UTC_TIMESTAMP(6)),
  (14, 'Oscar Wilde', 'Irish playwright, poet and wit of the Aesthetic movement.', UTC_TIMESTAMP(6)),
  (15, 'Charlotte Brontë', 'English novelist whose passionate first-person heroines broke with Victorian convention.', UTC_TIMESTAMP(6)),
  (16, 'Emily Brontë', 'English novelist and poet who wrote a single, stormy novel set on the Yorkshire moors.', UTC_TIMESTAMP(6)),
  (17, 'Leo Tolstoy', 'Russian novelist and moral thinker, author of vast panoramas of nineteenth-century Russian life.', UTC_TIMESTAMP(6)),
  (18, 'Fyodor Dostoevsky', 'Russian novelist who explored guilt, faith and freedom through intense psychological drama.', UTC_TIMESTAMP(6)),
  (19, 'Alexandre Dumas', 'French author of swashbuckling historical adventures and tales of revenge.', UTC_TIMESTAMP(6)),
  (20, 'Victor Hugo', 'French Romantic poet and novelist, champion of the poor and the outcast.', UTC_TIMESTAMP(6)),
  (21, 'Edgar Allan Poe', 'American poet and short-story writer, a pioneer of detective fiction and the macabre.', UTC_TIMESTAMP(6)),
  (22, 'Jonathan Swift', 'Anglo-Irish satirist and clergyman famous for his savage wit.', UTC_TIMESTAMP(6)),
  (23, 'Daniel Defoe', 'English trader, journalist and novelist, an early master of realistic fiction.', UTC_TIMESTAMP(6)),
  (24, 'Miguel de Cervantes', 'Spanish soldier and writer whose comic masterpiece is often called the first modern novel.', UTC_TIMESTAMP(6)),
  (25, 'Homer', 'The legendary ancient Greek poet credited with the great epics of the Trojan War and its aftermath.', UTC_TIMESTAMP(6)),
  (26, 'William Shakespeare', 'English playwright and poet, the most performed dramatist in the world.', UTC_TIMESTAMP(6)),
  (27, 'Walt Whitman', 'American poet whose expansive free verse celebrated democracy and the self.', UTC_TIMESTAMP(6)),
  (28, 'Emily Dickinson', 'American poet of compressed, startling lyrics, most published only after her death.', UTC_TIMESTAMP(6)),
  (29, 'Henry David Thoreau', 'American essayist and naturalist, advocate of simple living and civil disobedience.', UTC_TIMESTAMP(6)),
  (30, 'Marcus Aurelius', 'Roman emperor and Stoic philosopher who kept a private journal of moral reflections.', UTC_TIMESTAMP(6)),
  (31, 'Plato', 'Athenian philosopher, student of Socrates and founder of the Academy.', UTC_TIMESTAMP(6)),
  (32, 'Niccolò Machiavelli', 'Florentine diplomat and political theorist of the Renaissance.', UTC_TIMESTAMP(6)),
  (33, 'Sun Tzu', 'Ancient Chinese military strategist traditionally credited with a classic treatise on warfare.', UTC_TIMESTAMP(6)),
  (34, 'Frederick Douglass', 'American abolitionist, orator and writer who escaped slavery and fought to end it.', UTC_TIMESTAMP(6)),
  (35, 'Edgar Rice Burroughs', 'American pulp writer who created jungle heroes and Martian warlords.', UTC_TIMESTAMP(6)),
  (36, 'Wilkie Collins', 'English novelist whose sensation novels helped invent the modern mystery.', UTC_TIMESTAMP(6)),
  (37, 'Nathaniel Hawthorne', 'American novelist who probed the guilt and morality of Puritan New England.', UTC_TIMESTAMP(6)),
  (38, 'Kenneth Grahame', 'Scottish writer and banker who wrote gentle animal stories set along an English river.', UTC_TIMESTAMP(6)),
  (39, 'Rudyard Kipling', 'British writer and poet born in India, known for stories of the jungle and empire.', UTC_TIMESTAMP(6)),
  (40, 'Joseph Conrad', 'Polish-British novelist and former sailor who wrote about the sea and colonialism.', UTC_TIMESTAMP(6)),
  (41, 'F. Scott Fitzgerald', 'American novelist who chronicled the glamour and emptiness of the Jazz Age.', UTC_TIMESTAMP(6)),
  (42, 'Franz Kafka', 'Prague-born German-language writer of uncanny, bureaucratic nightmares.', UTC_TIMESTAMP(6)),
  (43, 'Edwin A. Abbott', 'English schoolmaster and theologian who wrote a mathematical satire.', UTC_TIMESTAMP(6)),
  (44, 'Louisa May Alcott', 'American novelist best known for her story of four sisters growing up in New England.', UTC_TIMESTAMP(6)),
  (45, 'Gaston Leroux', 'French journalist and author of mystery and Gothic fiction.', UTC_TIMESTAMP(6)),
  (46, 'Baroness Orczy', 'Hungarian-British novelist who created a masked hero of the French Revolution.', UTC_TIMESTAMP(6)),
  (47, 'Agatha Christie', 'English crime novelist, the best-selling fiction writer of all time.', UTC_TIMESTAMP(6)),
  (48, 'G. K. Chesterton', 'English writer, critic and creator of the priest-detective Father Brown.', UTC_TIMESTAMP(6)),
  (49, 'Sheridan Le Fanu', 'Irish writer of ghost stories and mystery novels of the Victorian era.', UTC_TIMESTAMP(6)),
  (50, 'H. Rider Haggard', 'English writer of adventure novels set in exotic and lost worlds.', UTC_TIMESTAMP(6)),
  (51, 'Voltaire', 'French Enlightenment writer and philosopher, famed for his satire and defense of free expression.', UTC_TIMESTAMP(6)),
  (52, 'Henrik Ibsen', 'Norwegian playwright, a founder of modern realist drama.', UTC_TIMESTAMP(6)),
  (53, 'Jack London', 'American novelist and adventurer who wrote of survival in the wild North.', UTC_TIMESTAMP(6)),
  (54, 'Frances Hodgson Burnett', 'English-American author of beloved children''s novels.', UTC_TIMESTAMP(6)),
  (55, 'L. M. Montgomery', 'Canadian author of stories set on Prince Edward Island.', UTC_TIMESTAMP(6)),
  (56, 'Thomas Hardy', 'English novelist and poet of rural Wessex and its tragic fates.', UTC_TIMESTAMP(6)),
  (57, 'Washington Irving', 'American essayist and storyteller of the early nineteenth century.', UTC_TIMESTAMP(6)),
  (58, 'Charlotte Perkins Gilman', 'American writer and social reformer whose fiction confronted women''s confinement.', UTC_TIMESTAMP(6)),
  (59, 'Friedrich Nietzsche', 'German philosopher who challenged conventional morality and religion.', UTC_TIMESTAMP(6)),
  (60, 'Kate Chopin', 'American writer of stories about women''s inner lives in Louisiana.', UTC_TIMESTAMP(6)),
  (61, 'Sophocles', 'Ancient Athenian tragedian whose plays still define classical tragedy.', UTC_TIMESTAMP(6));
INSERT IGNORE INTO books (id, title, description, author_id, isbn, cover_url, published_year, language, created_at, updated_at) VALUES
  (1, 'Pride and Prejudice', 'Elizabeth Bennet, quick-witted and proud of her judgement, clashes with the reserved and wealthy Mr. Darcy. As family scandal, gossip and misunderstanding pile up, both must confront their first impressions in this sparkling comedy of manners about love, money and marriage.', 1, NULL, NULL, 1813, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (2, 'Emma', 'Handsome, clever and rich, Emma Woodhouse amuses herself by arranging the love lives of her neighbours in a quiet English village. Her matchmaking schemes misfire spectacularly, teaching her uncomfortable lessons about vanity, class and her own heart.', 1, NULL, NULL, 1815, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (3, 'Sense and Sensibility', 'After their father''s death leaves them with little money, the sensible Elinor and the passionate Marianne Dashwood navigate heartbreak, secret engagements and fickle suitors, each learning something of the other''s way of loving.', 1, NULL, NULL, 1811, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (4, 'Persuasion', 'Eight years after being persuaded to break off her engagement to a penniless naval officer, Anne Elliot meets him again, now a wealthy captain. A quiet, aching story of second chances, constancy and regret.', 1, NULL, NULL, 1817, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (5, 'Northanger Abbey', 'Catherine Morland, a young reader devoted to lurid Gothic novels, visits Bath and then a mysterious old abbey, where her overheated imagination finds secrets everywhere. A playful parody of horror fiction and a coming-of-age romance.', 1, NULL, NULL, 1817, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (6, 'Frankenstein', 'Victor Frankenstein, a brilliant and obsessive student, assembles a living creature from dead matter and recoils in horror from what he has made. Abandoned and rejected, the creature seeks understanding and then revenge in a tragedy about ambition, responsibility and loneliness.', 2, NULL, NULL, 1818, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (7, 'Dracula', 'A young solicitor travels to a remote Transylvanian castle and discovers his client is an ancient vampire bound for England. Told through letters and diaries, a band of friends led by Professor Van Helsing races to stop the Count before he claims them all.', 3, NULL, NULL, 1897, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (8, 'The Time Machine', 'A Victorian inventor travels hundreds of thousands of years into the future and finds humanity split into the gentle, childlike Eloi and the subterranean Morlocks. A haunting speculation about class, evolution and the fate of civilisation.', 4, NULL, NULL, 1895, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (9, 'The War of the Worlds', 'Cylinders fall from the sky over the English countryside and Martians emerge in towering tripods armed with heat-rays. A narrator flees across a collapsing England in the original alien-invasion story.', 4, NULL, NULL, 1898, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (10, 'The Invisible Man', 'A bandaged stranger arrives at a village inn, hiding a scientific discovery that has made him invisible and slowly unhinged him. Power without accountability turns a brilliant chemist into a menace.', 4, NULL, NULL, 1897, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (11, 'The Island of Doctor Moreau', 'A shipwrecked man lands on a remote island where a disgraced scientist surgically transforms animals into human-like beings. A disturbing fable about cruelty, science and what makes us human.', 4, NULL, NULL, 1896, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (12, 'Twenty Thousand Leagues Under the Seas', 'A marine biologist and his companions are taken aboard the Nautilus, a marvellous submarine commanded by the enigmatic Captain Nemo, and voyage through sunken forests, polar ice and the ruins of Atlantis.', 5, NULL, NULL, 1870, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (13, 'Around the World in Eighty Days', 'The punctual English gentleman Phileas Fogg wagers his fortune that he can circle the globe in eighty days. With his resourceful valet Passepartout and a detective on his trail, he races by steamer, train and elephant.', 5, NULL, NULL, 1872, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (14, 'Journey to the Center of the Earth', 'An impetuous professor, his reluctant nephew and a stoic guide descend into an Icelandic volcano and discover a vast underground world of prehistoric creatures and subterranean seas.', 5, NULL, NULL, 1864, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (15, 'A Study in Scarlet', 'Army doctor John Watson takes rooms with an eccentric consulting detective, Sherlock Holmes, and is soon drawn into a baffling London murder whose roots lie far away in the American West.', 6, NULL, NULL, 1887, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (16, 'The Hound of the Baskervilles', 'A family curse, a spectral hound and a death on the fog-bound Devon moors bring Sherlock Holmes and Dr. Watson to Baskerville Hall, where reason must contend with legend.', 6, NULL, NULL, 1902, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (17, 'The Adventures of Sherlock Holmes', 'Twelve cases of the great detective, from a royal blackmail scandal to a league of red-headed men and a deadly speckled band, showcasing Holmes''s dazzling powers of observation and deduction.', 6, NULL, NULL, 1892, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (18, 'The Lost World', 'A combative professor leads a reporter, a sceptical scientist and a big-game hunter to a remote South American plateau where dinosaurs still roam and ape-men wage war.', 6, NULL, NULL, 1912, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (19, 'Great Expectations', 'The orphan Pip, raised by his harsh sister on the Kentish marshes, receives a fortune from a mysterious benefactor and is sent to London to become a gentleman, where he must reckon with ambition, snobbery and loyalty.', 7, NULL, NULL, 1861, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (20, 'A Tale of Two Cities', 'Between London and Paris in the years of the French Revolution, a family is caught in the Terror, and a dissolute lawyer finds an unlikely chance at redemption and sacrifice.', 7, NULL, NULL, 1859, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (21, 'Oliver Twist', 'An orphan born in a workhouse escapes to London and falls in with a gang of child pickpockets run by the scheming Fagin. A fierce indictment of poverty and cruelty in Victorian England.', 7, NULL, NULL, 1838, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (22, 'A Christmas Carol', 'The miserly Ebenezer Scrooge is visited on Christmas Eve by the ghost of his former partner and three spirits who show him his past, present and future, offering him one last chance to change.', 7, NULL, NULL, 1843, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (23, 'Moby-Dick', 'Ishmael signs aboard the whaler Pequod and learns that Captain Ahab is bent on revenge against the white whale that took his leg. An epic of obsession, the sea and the limits of knowledge.', 8, NULL, NULL, 1851, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (24, 'Adventures of Huckleberry Finn', 'Escaping his abusive father, Huck Finn rafts down the Mississippi with Jim, a man fleeing slavery. Their journey through river towns full of con men and feuds tests Huck''s conscience and friendship.', 9, NULL, NULL, 1884, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (25, 'The Adventures of Tom Sawyer', 'Mischievous Tom Sawyer whitewashes fences, plays pirate, witnesses a graveyard murder and hunts for buried treasure in a sleepy Missouri town on the Mississippi River.', 9, NULL, NULL, 1876, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (26, 'A Connecticut Yankee in King Arthur''s Court', 'A practical nineteenth-century engineer wakes up in Camelot and uses modern technology to pose as a great magician, with comic and then catastrophic results. A satire of chivalry, superstition and progress.', 9, NULL, NULL, 1889, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (27, 'Alice''s Adventures in Wonderland', 'Alice follows a hurried White Rabbit down a hole into a world of shrinking potions, a grinning cat, a mad tea party and a furious Queen of Hearts, where logic turns delightfully upside down.', 10, NULL, NULL, 1865, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (28, 'Through the Looking-Glass', 'Alice climbs through a mirror into a land laid out like a chessboard, meeting Tweedledum and Tweedledee, Humpty Dumpty and the White Knight as she advances to become a queen.', 10, NULL, NULL, 1871, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (29, 'The Wonderful Wizard of Oz', 'A cyclone carries Dorothy from Kansas to the magical land of Oz. With a Scarecrow, a Tin Woodman and a Cowardly Lion, she follows the yellow brick road to seek the Wizard''s help in getting home.', 11, NULL, NULL, 1900, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (30, 'Peter and Wendy', 'Peter Pan flies the Darling children to Neverland, home of the Lost Boys, mermaids and the villainous Captain Hook, in a bittersweet story about the joys of childhood and the necessity of growing up.', 12, NULL, NULL, 1911, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (31, 'Treasure Island', 'Young Jim Hawkins finds a treasure map and sails for a distant island, only to discover that the charming one-legged cook Long John Silver is leading a pirate mutiny.', 13, NULL, NULL, 1883, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (32, 'Strange Case of Dr Jekyll and Mr Hyde', 'A London lawyer investigates the link between his respectable friend Dr. Jekyll and the brutal, repellent Mr. Hyde, uncovering a chemical experiment that splits a man''s good and evil natures.', 13, NULL, NULL, 1886, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (33, 'Kidnapped', 'Betrayed by his miserly uncle and sold onto a ship, young David Balfour escapes with the Jacobite rebel Alan Breck and flees across the Scottish Highlands after a political murder.', 13, NULL, NULL, 1886, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (34, 'The Picture of Dorian Gray', 'A beautiful young man wishes that his portrait would age instead of him. As he sinks into a life of pleasure and cruelty, the hidden painting records every sin in this decadent, witty Gothic tale.', 14, NULL, NULL, 1890, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (35, 'The Importance of Being Earnest', 'Two young gentlemen invent fictitious alter egos to escape social obligations, leading to romantic confusion, cucumber sandwiches and one of the most quotable comedies of the English stage.', 14, NULL, NULL, 1895, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (36, 'Jane Eyre', 'An orphaned governess with a fierce sense of self-worth falls in love with her brooding employer, Mr. Rochester, at Thornfield Hall, where a terrible secret is locked away in the attic.', 15, NULL, NULL, 1847, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (37, 'Wuthering Heights', 'On the wild Yorkshire moors, the foundling Heathcliff and Catherine Earnshaw share a consuming love that turns to vengeance across two generations of two families.', 16, NULL, NULL, 1847, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (38, 'War and Peace', 'Following aristocratic Russian families through the Napoleonic Wars, from glittering ballrooms to the burning of Moscow, Tolstoy weaves love, war and philosophy of history into a vast panorama.', 17, NULL, NULL, 1869, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (39, 'Anna Karenina', 'A married aristocrat''s passionate affair with a dashing cavalry officer scandalises Russian high society, while a landowner''s search for meaning on his estate offers a counterpoint about family and faith.', 17, NULL, NULL, 1878, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (40, 'Crime and Punishment', 'Raskolnikov, an impoverished former student in St. Petersburg, murders a pawnbroker to prove a theory about extraordinary men, then is tormented by guilt and a patient detective.', 18, NULL, NULL, 1866, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (41, 'The Brothers Karamazov', 'Three very different brothers and their dissolute father are drawn into passion, rivalry and murder in a profound drama about faith, doubt, free will and moral responsibility.', 18, NULL, NULL, 1880, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (42, 'The Count of Monte Cristo', 'Wrongly imprisoned on his wedding day, the sailor Edmond Dantès escapes after fourteen years, finds a hidden fortune and returns as a mysterious count to take elaborate revenge on those who betrayed him.', 19, NULL, NULL, 1844, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (43, 'The Three Musketeers', 'The hot-headed young d''Artagnan joins the musketeers Athos, Porthos and Aramis to defend the queen''s honour against Cardinal Richelieu and the deadly Milady de Winter.', 19, NULL, NULL, 1844, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (44, 'Les Misérables', 'Released after nineteen years in prison for stealing bread, Jean Valjean rebuilds his life while being hunted by the relentless Inspector Javert, amid poverty and revolution in nineteenth-century France.', 20, NULL, NULL, 1862, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (45, 'The Hunchback of Notre-Dame', 'In medieval Paris, the deformed bell-ringer Quasimodo, the obsessed archdeacon Frollo and others fall for the Romani dancer Esmeralda, with the great cathedral looming over their fates.', 20, NULL, NULL, 1831, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (46, 'Tales of Mystery and Imagination', 'Poe''s darkest tales: a crumbling house and its doomed family, a beating heart beneath the floorboards, a masked plague at a prince''s ball, and the first detective, C. Auguste Dupin.', 21, NULL, NULL, 1845, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (47, 'The Raven and Other Poems', 'Musical, melancholy verse haunted by lost love and death, led by the famous midnight visit of a raven that answers every question with a single word.', 21, NULL, NULL, 1845, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (48, 'Gulliver''s Travels', 'The ship''s surgeon Lemuel Gulliver is shipwrecked among tiny Lilliputians, giants, absent-minded scientists and rational horses, in a biting satire of human politics and pride.', 22, NULL, NULL, 1726, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (49, 'Robinson Crusoe', 'The sole survivor of a shipwreck spends twenty-eight years on a remote island, building shelter, farming, wrestling with faith and finally encountering another human being.', 23, NULL, NULL, 1719, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (50, 'Don Quixote', 'A Spanish gentleman who has read too many chivalric romances declares himself a knight-errant and rides out with his practical squire Sancho Panza, tilting at windmills in a comic, tender masterpiece.', 24, NULL, NULL, 1605, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (51, 'The Odyssey', 'After the fall of Troy, the cunning Odysseus spends ten years struggling home across a sea of monsters, witches and angry gods, while his wife Penelope holds off a crowd of suitors.', 25, NULL, NULL, NULL, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (52, 'The Iliad', 'In the tenth year of the Trojan War, the wrath of the warrior Achilles brings disaster to the Greeks and to Troy''s champion Hector, in the ancient epic of glory, grief and mortality.', 25, NULL, NULL, NULL, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (53, 'Hamlet', 'Prince Hamlet learns from his father''s ghost that his uncle murdered the king and married his mother. Torn by doubt, he feigns madness as he plots revenge in Shakespeare''s great tragedy of indecision.', 26, NULL, NULL, 1603, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (54, 'Macbeth', 'Spurred on by witches'' prophecies and his ruthless wife, a Scottish general murders his king and seizes the throne, spiralling into tyranny, paranoia and bloodshed.', 26, NULL, NULL, 1623, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (55, 'Romeo and Juliet', 'Two young lovers from feuding families in Verona marry in secret, but a street brawl, a banishment and a desperate plan lead to tragedy.', 26, NULL, NULL, 1597, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (56, 'A Midsummer Night''s Dream', 'Lovers lost in an enchanted forest, quarrelling fairy royalty, a mischievous Puck and a troupe of amateur actors collide in Shakespeare''s magical comedy of love''s confusions.', 26, NULL, NULL, 1600, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (57, 'Leaves of Grass', 'Whitman''s lifelong collection of free verse sings of the body, the soul, democracy and the teeming life of nineteenth-century America.', 27, NULL, NULL, 1855, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (58, 'Poems by Emily Dickinson', 'Short, intense lyrics on death, nature, faith and the inner life, written with dashes, slant rhyme and startling imagery by a reclusive poet from Amherst.', 28, NULL, NULL, 1890, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (59, 'Walden', 'Thoreau''s account of two years living in a cabin he built by Walden Pond, reflecting on simplicity, self-reliance, nature and the quiet desperation of modern life.', 29, NULL, NULL, 1854, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (60, 'Meditations', 'Private notes of a Roman emperor reminding himself how to live: accept what cannot be changed, act with justice, and remember that everything passes. A foundational text of Stoicism.', 30, NULL, NULL, NULL, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (61, 'The Republic', 'Socrates and his companions ask what justice is, imagining an ideal city ruled by philosopher-kings and offering the allegory of the cave.', 31, NULL, NULL, NULL, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (62, 'The Prince', 'A blunt Renaissance handbook on how rulers gain and keep power, arguing that effective leaders must sometimes be feared rather than loved.', 32, NULL, NULL, 1532, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (63, 'The Art of War', 'An ancient Chinese treatise on strategy, deception and leadership whose maxims about knowing yourself and your enemy are still applied far beyond the battlefield.', 33, NULL, NULL, NULL, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (64, 'Narrative of the Life of Frederick Douglass', 'Douglass''s own account of his childhood in slavery, his secret struggle to learn to read and his escape to freedom, a powerful testimony that fuelled the abolitionist movement.', 34, NULL, NULL, 1845, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (65, 'A Princess of Mars', 'Confederate veteran John Carter is mysteriously transported to Mars, where low gravity makes him a superhuman warrior among four-armed giants and he fights to win the princess Dejah Thoris.', 35, NULL, NULL, 1912, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (66, 'Tarzan of the Apes', 'Orphaned in the African jungle and raised by apes, an English lord''s son grows into a formidable hunter, teaches himself to read and meets the outside world for the first time.', 35, NULL, NULL, 1912, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (67, 'The Moonstone', 'A sacred Indian diamond vanishes from a young woman''s bedroom the night after her birthday, and the patient Sergeant Cuff investigates in what is often called the first English detective novel.', 36, NULL, NULL, 1868, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (68, 'The Woman in White', 'A drawing teacher meets a ghostly woman in white on a moonlit road, setting off a conspiracy of stolen identities, asylums and a villainous count in a classic sensation novel.', 36, NULL, NULL, 1859, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (69, 'The Scarlet Letter', 'In Puritan Boston, Hester Prynne is forced to wear a scarlet A for adultery and refuses to name her lover, while the town''s revered minister is consumed by secret guilt.', 37, NULL, NULL, 1850, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (70, 'The Wind in the Willows', 'The gentle Mole, the riverside Rat, the wise Badger and the reckless, motor-car-mad Toad share picnics, misadventures and a daring rescue of Toad Hall along an English river.', 38, NULL, NULL, 1908, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (71, 'The Jungle Book', 'Stories of Mowgli, a boy raised by wolves and taught by Baloo the bear and Bagheera the panther, and of other animals including the brave mongoose Rikki-Tikki-Tavi.', 39, NULL, NULL, 1894, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (72, 'Heart of Darkness', 'The sailor Marlow travels up the Congo River in search of the ivory trader Kurtz and confronts the brutality of colonial exploitation and the darkness within human nature.', 40, NULL, NULL, 1899, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (73, 'The Great Gatsby', 'On Long Island in the summer of 1922, the mysterious millionaire Jay Gatsby throws lavish parties in the hope of rekindling his romance with Daisy Buchanan, as narrated by her cousin Nick.', 41, NULL, NULL, 1925, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (74, 'The Metamorphosis', 'Travelling salesman Gregor Samsa wakes one morning transformed into a monstrous insect, and his family''s response to his condition becomes a dark parable of alienation and duty.', 42, NULL, NULL, 1915, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (75, 'Flatland', 'A Square living in a two-dimensional world is visited by a Sphere and learns of the third dimension, in a mathematical fable that satirises Victorian social hierarchy.', 43, NULL, NULL, 1884, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (76, 'Little Women', 'The four March sisters, Meg, Jo, Beth and Amy, grow up in Civil War-era New England, facing poverty, ambition, love and loss with warmth and humour.', 44, NULL, NULL, 1868, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (77, 'The Phantom of the Opera', 'A masked genius haunts the cellars of the Paris Opera, tutoring the young soprano Christine Daaé and terrorising anyone who stands between them.', 45, NULL, NULL, 1910, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (78, 'The Scarlet Pimpernel', 'During the Reign of Terror, a mysterious Englishman known only by his flower emblem smuggles French aristocrats from the guillotine, while his wife unknowingly helps his enemies close in.', 46, NULL, NULL, 1905, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (79, 'The Mysterious Affair at Styles', 'A wealthy widow is poisoned at her Essex country house, and a retired Belgian detective, Hercule Poirot, untangles the household''s secrets in his first case.', 47, NULL, NULL, 1920, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (80, 'The Innocence of Father Brown', 'A mild, umbrella-carrying Catholic priest solves baffling crimes through his deep understanding of human sin, in a collection of witty and paradoxical detective stories.', 48, NULL, NULL, 1911, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (81, 'The Man Who Was Thursday', 'A poet-turned-detective infiltrates a council of anarchists named for the days of the week, only to find the conspiracy growing stranger and more dreamlike at every turn.', 48, NULL, NULL, 1908, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (82, 'Carmilla', 'In a lonely Styrian castle, a young woman befriends a beautiful, languid guest whose arrival coincides with a wasting sickness among local girls. An early and influential vampire novella.', 49, NULL, NULL, 1872, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (83, 'King Solomon''s Mines', 'The hunter Allan Quatermain leads an expedition across desert and mountains in search of a lost brother and the legendary diamond mines of King Solomon.', 50, NULL, NULL, 1885, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (84, 'Candide', 'Taught that this is the best of all possible worlds, the naive Candide endures war, earthquake, shipwreck and the Inquisition in Voltaire''s brisk, savage satire of optimism.', 51, NULL, NULL, 1759, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (85, 'A Doll''s House', 'Nora Helmer seems the perfect cheerful wife, until a secret loan and a blackmailer force her to see her marriage clearly, ending in a door slam that shook European theatre.', 52, NULL, NULL, 1879, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (86, 'The Call of the Wild', 'Buck, a pampered dog from California, is stolen and sold as a sled dog in the Klondike Gold Rush, where he learns to survive and answers an ancient call to the wild.', 53, NULL, NULL, 1903, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (87, 'White Fang', 'Born in the frozen Yukon, a wolf-dog endures hunger and cruel masters before finding trust and loyalty with a kind man, mirroring the journey of The Call of the Wild in reverse.', 53, NULL, NULL, 1906, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (88, 'The Secret Garden', 'Sent to live in a gloomy Yorkshire manor, the sour orphan Mary Lennox discovers a locked, neglected garden and, with new friends, brings it and herself back to life.', 54, NULL, NULL, 1911, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (89, 'Anne of Green Gables', 'An imaginative, talkative red-haired orphan is sent by mistake to an elderly brother and sister on Prince Edward Island and wins over the whole town of Avonlea.', 55, NULL, NULL, 1908, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (90, 'Tess of the d''Urbervilles', 'A poor country girl learns her family descends from nobility, setting in motion a chain of exploitation, love and injustice in Hardy''s tragic portrait of rural Wessex.', 56, NULL, NULL, 1891, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (91, 'The Legend of Sleepy Hollow', 'The lanky, superstitious schoolmaster Ichabod Crane courts a wealthy farmer''s daughter in a Hudson Valley village said to be haunted by a headless horseman.', 57, NULL, NULL, 1820, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (92, 'The Yellow Wallpaper', 'Confined to a nursery room for a ''rest cure'', a young mother becomes obsessed with the patterns in its peeling yellow wallpaper, in a chilling story of psychological imprisonment.', 58, NULL, NULL, 1892, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (93, 'Thus Spoke Zarathustra', 'A prophet descends from his mountain solitude to teach humanity about the overman, eternal recurrence and the death of God, in Nietzsche''s poetic philosophical novel.', 59, NULL, NULL, 1883, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (94, 'The Awakening', 'During a summer on the Gulf Coast, Edna Pontellier awakens to her own desires and independence, defying the expectations placed on a wife and mother in Creole society.', 60, NULL, NULL, 1899, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6)),
  (95, 'Oedipus Rex', 'King Oedipus vows to find the murderer whose crime has brought plague upon Thebes, and his relentless investigation leads to a horrifying truth about himself.', 61, NULL, NULL, NULL, 'en', UTC_TIMESTAMP(6), UTC_TIMESTAMP(6));
